"""Explicit mock units or exact, offline tokenizer counts for VIR text.

Counts exclude chat templates and automatically inserted special tokens. They
must not be reported as complete LLM request token counts. This module never
downloads a tokenizer, imports model weights, or falls back to a byte estimate.
"""

from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Protocol, runtime_checkable


class MissingTokenizerError(ValueError):
    """A requested tokenizer or its optional runtime is unavailable."""


@runtime_checkable
class TokenCounter(Protocol):
    """Counting contract; always carry the unit identity into result metadata."""

    name: str
    is_model_tokenizer: bool

    def count(self, text: str) -> int:
        """Count the complete input; implementations must never truncate it."""
        ...


class MockByteCounter:
    """Deterministic UTF-8 byte units for tests, never genuine model tokens."""

    name = "mock:utf8-bytes"
    is_model_tokenizer = False

    def count(self, text: str) -> int:
        if not isinstance(text, str):
            raise TypeError("Counted text must be a string.")
        return len(text.encode("utf-8"))


class LocalTokenizer:
    """Load one local tokenizer.json using the optional Hugging Face runtime.

    The optional dependency is imported only when this adapter is constructed.
    No Hub API, remote custom code, model weights, or implicit fallback is used.
    Saved padding/truncation settings are disabled so the complete representation
    is counted. The name contains the SHA-256 of the loaded tokenizer file.
    """

    is_model_tokenizer = True

    def __init__(self, path: str | Path) -> None:
        candidate = Path(path).expanduser()
        if candidate.is_dir():
            candidate = candidate / "tokenizer.json"
        if not candidate.is_file():
            raise MissingTokenizerError(
                f"Tokenizer bulunamadı: {candidate}. Yerel tokenizer.json yolunu "
                "verin. Runtime gerekiyorsa: pip install '.[tokenizers]'. "
                "Yalnız test için --tokenizer mock kullanabilirsiniz; mock "
                "birimleri gerçek token değildir."
            )

        try:
            from tokenizers import Tokenizer
        except ImportError as exc:
            raise MissingTokenizerError(
                "Tokenizer runtime bulunamadı. Kurulum: pip install '.[tokenizers]'. "
                "Otomatik tahmini token sayımı yapılmadı."
            ) from exc

        self.path = candidate.resolve()
        try:
            self.sha256 = hashlib.sha256(self.path.read_bytes()).hexdigest()
            self._tokenizer = Tokenizer.from_file(str(self.path))
            self._tokenizer.no_padding()
            self._tokenizer.no_truncation()
        except Exception as exc:
            raise ValueError(
                f"Tokenizer yüklenemedi: {self.path}. Geçerli bir tokenizer.json "
                f"ve uyumlu tokenizers runtime kullanın: {exc}"
            ) from exc
        self.name = f"local:{self.path.parent.name}/{self.path.name}:sha256:{self.sha256}"

    def count(self, text: str) -> int:
        if not isinstance(text, str):
            raise TypeError("Counted text must be a string.")
        return len(self._tokenizer.encode(text, add_special_tokens=False).ids)


def load_tokenizer(spec: str) -> TokenCounter:
    """Resolve an explicit ``mock`` selection or a local file/directory path."""
    if not isinstance(spec, str) or not spec.strip():
        raise MissingTokenizerError(
            "Bir yerel tokenizer.json yolu belirtin. Runtime kurulumu: "
            "pip install '.[tokenizers]'. Test için açıkça 'mock' seçilebilir."
        )
    if spec == "mock":
        return MockByteCounter()
    return LocalTokenizer(spec)
